 private void release(Lease l,String state,String error,boolean failure){long n=now();db.update("UPDATE b_reconciliation_task SET state=?,last_error=?,failure_count=IF(?=1,failure_count+1,0),alerted=alerted OR failure_count+?>=5,next_attempt_ms=?,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE task_id=?",state,error,failure?1:0,failure?1:0,n+2000,n,l.taskId());}
 public void defer(Lease l,String error,boolean conflict){tx.executeWithoutResult(s->{var t=task(l);if(!current(t,l))return;int failures=((Number)t.get("failure_count")).intValue()+1;if(failures>=5&&!Boolean.TRUE.equals(t.get("alerted")))org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){System.getLogger(ReconciliationRepository.class.getName()).log(System.Logger.Level.WARNING,"Reconciliation recovery requires attention; taskId="+l.taskId()+", code="+error+", automaticRecovery=continuing");}});String state=conflict?"REVIEW_REQUIRED":t.get("state").equals("SUBMITTING")?"SUBMIT_UNKNOWN":"WAITING_DEPENDENCY";long n=now();db.update("UPDATE b_reconciliation_task SET state=?,last_error=?,failure_count=?,alerted=alerted OR ?>=5,next_attempt_ms=?,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE task_id=?",state,error,failures,failures,n+Math.min(30000L,2000L*(1L<<Math.min(4,failures-1)))+java.util.concurrent.ThreadLocalRandom.current().nextLong(251),n,l.taskId());db.update("UPDATE b_reconciliation_submission SET state=?,updated_at_ms=? WHERE task_id=? AND state<>'ACKNOWLEDGED'",conflict?"REVIEW_REQUIRED":"UNKNOWN",n,l.taskId());});}
